/**
 * Regenerates lib/achievements-client.js from scripts/achievements.mjs.
 *
 * The definitions must be byte-identical in both places: the build-time scorer
 * and the live browser view have to agree, or Sunday's projected points will
 * not match Tuesday's official ones.
 */
import { readFileSync, writeFileSync } from 'node:fs';

const SRC = 'scripts/achievements.mjs';
const OUT = 'lib/achievements-client.js';

const header = `// Browser copy of ${SRC}.
//
// Generated by scripts/sync-achievements.mjs. Do not edit directly -- edit
// ${SRC} and run \`npm run sync:achievements\`.

`;

writeFileSync(OUT, header + readFileSync(SRC, 'utf8'));
console.log(`Synced ${SRC} -> ${OUT}`);
